        var context = new RecordMutationContext(pageId, "config_page_column", entity.Id, Convert.ToString(entity.YzProjectId, CultureInfo.InvariantCulture) ?? string.Empty, values, deleting, transaction, IsCreate: allFields && !deleting);
        foreach (var observer in observers) await observer.BeforeCommitAsync(context, cancellationToken);
    }
}
